from itertools import product
import copy
import sys
sys.setrecursionlimit(1 << 20)

N, H, W = map(int, input().split())
AB = list()

for _ in range(N):
    a, b = map(int, input().split())
    AB.append([a, b])
global ans
ans = False
C = [[True for _ in range(W)] for i in range(H)]

def dfs(x, y, rem, masu):
    global ans
    if ans:
        return
    if all(all(row) for row in masu):
        ans = True
        return
    if y == W:
        x += 1
        y = 0
    if x == H:
        return
    if masu[x][y]:
        dfs(x, y + 1, rem, masu)
        return
    for i in range(len(rem)):
        a, b = rem[i]
        for h, w in [(a, b), (b, a)]:
            if x + h <= H and y + w <= W:
                if all(not masu[x + dx][y + dy] for dx in range(h) for dy in range(w)):
                    new_masu = copy.deepcopy(masu)
                    for dx in range(h):
                        for dy in range(w):
                            new_masu[x + dx][y + dy] = True
                    new_rem = rem[:i] + rem[i + 1:]
                    dfs(x, y + w, new_rem, new_masu)

for bits in product([0, 1], repeat=N):
    item = [AB[i] for i in range(N) if bits[i]]
    masu = [[False for _ in range(W)] for _ in range(H)]
    area_sum = sum(a * b for a, b in item)
    if area_sum != H * W:
        continue
    dfs(0, 0, item, masu)

if ans:
    print("Yes")
else:
    print("No")
